import type { PricingTable } from "../value-objects/pricing-table.js";
import { type LiteLLMEntry, priceOfEntry } from "./litellm-entry.js";
import snapshot from "./litellm-snapshot.json" with { type: "json" };

// The snapshot is generated by scripts/update-pricing.ts, which documents its filter; TypeScript checks every entry
// against LiteLLMEntry here, so the entries are converted without parsing them again at load.
const entries: Readonly<Record<string, LiteLLMEntry>> = snapshot.prices;

/** The kit's snapshot of LiteLLM's model price list, as a table ready for `createPricing`. */
export const litellmPrices: PricingTable = Object.fromEntries(
  Object.entries(entries).map(([model, entry]) => [model, priceOfEntry(entry)])
);

/**
 * The snapshot's version: the date (UTC) and, after a `+`, the commit of LiteLLM's
 * `model_prices_and_context_window.json` it was generated from, such as `2026-10-25+de5dc5b2…` (40 hex digits); the
 * date is that commit's, not the day the snapshot was generated. A host records it next to the costs it computes with
 * `litellmPrices`.
 */
export const litellmPricesVersion: string = snapshot.version;
